answer:
```python
class ListDict(list, dict):
    def __init__(self, keys, values):
        list.__init__(self, values)
        dict.__init__(self, zip(keys, values))
    def __missing__(self, key):
        raise KeyError(key)

def transform_record(record: dict, schema: dict) -> Any:
    output_type = schema.get('__output_type__', 'dict')
    strict = schema.get('__strict__', False)
    # Extract field names that are actual schema keys (excluding special keys)
    schema_keys = [k for k in schema if not k.startswith('__')]
    # Strict mode check: if strict, all record keys must be in schema_keys
    if strict:
        unexpected = set(record) - set(schema_keys)
        if unexpected:
            raise KeyError(f"Unexpected keys in record: {unexpected}")
    transformed = {}
    # Coerce according to schema, pass through fields not in schema unchanged
    for key, value in record.items():
        if key in schema_keys:
            try:
                transformed[key] = schema[key](value)
            except Exception as e:
                # Propagate coercion errors
                raise
        else:
            transformed[key] = value
    if output_type == 'list':
