answer:
```python
from collections.abc import Mapping
from typing import Any

def transform_record(record: dict, schema: dict) -> Any:
    output_type = schema.get('__output_type__', 'dict')
    strict = schema.get('__strict__', False)

    # Extract field keys and their target types, excluding special keys
    field_keys = [k for k in schema if not k.startswith('__')]
    field_types = {k: schema[k] for k in field_keys}

    if strict:
        unexpected = set(record) - set(field_keys)
        if unexpected:
            raise KeyError(f'Unexpected fields in record: {unexpected}')

    # Coerce known fields per schema; pass through others unchanged
    transformed = {}
    for key in record:
        if key in field_types:
            transformed[key] = field_types[key](record[key])
        else:
            transformed[key] = record[key]

    # Decide on output format
    if output_type == 'list':
        # Output in schema-defined order
        values = [transformed.get(k) for k in field_keys]

        # Build a thin wrapper that is both list and dict-like
        class ListDict(list, Mapping):
            def __getitem__(self, key):
                if isinstance(key, int):
                    return super().__getitem__(key)
                if key in field_keys:
                    idx = field_keys.index(key)
                    return self[idx]
                raise KeyError(key)
            def __iter__(self):
                return iter(field_keys)
            def __len__(self):
                return len(field_keys)
            def keys(self):
                return field_keys
            def items(self):
                return zip(field_keys, self)
            def values(self):
                return self
        return ListDict(values)

    else:
        return transformed
```

