I have a utility module for parsing configuration files. It works great for basic cases, but I'm adding support for environment variable interpolation and override precedence. Can you update `resolve_config_value` to make all these tests pass?

```python
import os
from typing import Any, Dict, Optional

_SENTINEL = object()

def resolve_config_value(
    key: str,
    config: Dict[str, Any],
    env_prefix: str = "APP",
    default: Any = _SENTINEL,
) -> Any:
    """Resolve a configuration value using the following precedence:
    1. Environment variable (APP_{KEY.upper()}) overrides everything
    2. Value from config dict
    3. Provided default
    4. Raise KeyError if none of the above exist

    Numeric strings from env vars are automatically cast to int or float.
    Boolean strings ('true'/'false', case-insensitive) are cast to bool.
    """
    pass


# --- Existing tests (all currently pass with original implementation) ---

def test_returns_config_value():
    cfg = {"timeout": 30}
    assert resolve_config_value("timeout", cfg) == 30

def test_returns_default_when_missing():
    cfg = {}
    assert resolve_config_value("retries", cfg, default=3) == 3

def test_raises_keyerror_when_no_default():
    cfg = {}
    try:
        resolve_config_value("missing_key", cfg)
        assert False, "Should have raised"
    except KeyError:
        pass

def test_config_value_can_be_none():
    cfg = {"debug": None}
    assert resolve_config_value("debug", cfg) is None

def test_config_value_string():
    cfg = {"host": "localhost"}
    assert resolve_config_value("host", cfg) == "localhost"

# --- New tests for env var interpolation ---

def test_env_var_overrides_config(monkeypatch):
    monkeypatch.setenv("APP_TIMEOUT", "60")
    cfg = {"timeout": 30}
    assert resolve_config_value("timeout", cfg) == 60

def test_env_var_cast_to_float(monkeypatch):
    monkeypatch.setenv("APP_THRESHOLD", "0.75")
    cfg = {"threshold": 0.5}
    result = resolve_config_value("threshold", cfg)
    assert isinstance(result, float)
    assert result == 0.75

def test_env_var_cast_bool_true(monkeypatch):
    monkeypatch.setenv("APP_DEBUG", "true")
    cfg = {"debug": False}
    assert resolve_config_value("debug", cfg) is True

def test_env_var_cast_bool_false(monkeypatch):
    monkeypatch.setenv("APP_DEBUG", "FALSE")
    cfg = {"debug": True}
    assert resolve_config_value("debug", cfg) is False

def test_env_var_string_preserved(monkeypatch):
    monkeypatch.setenv("APP_HOST", "prod.example.com")
    cfg = {"host": "localhost"}
    assert resolve_config_value("host", cfg) == "prod.example.com"

def test_env_var_overrides_default(monkeypatch):
    monkeypatch.setenv("APP_WORKERS", "8")
    cfg = {}
    assert resolve_config_value("workers", cfg, default=4) == 8

def test_custom_prefix(monkeypatch):
    monkeypatch.setenv("MYAPP_PORT", "9090")
    cfg = {"port": 8080}
    assert resolve_config_value("port", cfg, env_prefix="MYAPP") == 9090

def test_env_var_does_not_override_config_when_absent(monkeypatch):
    monkeypatch.delenv("APP_LOGLEVEL", raising=False)
    cfg = {"loglevel": "info"}
    assert resolve_config_value("loglevel", cfg) == "info"

def test_config_takes_precedence_over_env_var(monkeypatch):
    # Config dict values should take precedence over environment variables
    # when both are present
    monkeypatch.setenv("APP_TIMEOUT", "60")
    cfg = {"timeout": 30}
    assert resolve_config_value("timeout", cfg) == 30
```

