answer:
def percentile(data: List[float], p: float) -> float:
    if not data:
        raise ValueError("data must be non-empty")
    if not (0 <= p <= 100):
        raise ValueError("percentile 'p' must be in [0, 100]")
    sorted_data = sorted(data)
    n = len(sorted_data)
    if n == 1:
        return float(sorted_data[0])
    # Compute the rank using the default numpy.percentile method (linear interpolation)
    rank = p / 100 * (n - 1)
    lower_index = int(rank)
    upper_index = min(lower_index + 1, n - 1)
    fraction = rank - lower_index
    lower_value = sorted_data[lower_index]
    upper_value = sorted_data[upper_index]
    return float(lower_value + fraction * (upper_value - lower_value))

Here's an implementation that matches numpy's default 'linear' interpolation percentile behavior, and should pass all your tests:

```python
def percentile(data: List[float], p: float) -> float:
    if not 0 <= p <= 100:
        raise ValueError("Percentile p must be in the range [0, 100]")
    if not data:
        raise ValueError("Data list must not be empty")

    sorted_data = sorted(data)
    n = len(sorted_data)
    if n == 1:
        return float(sorted_data[0])

    # Compute the rank using numpy's method: h = (p/100)*(n-1) + 1
    h = (p / 100) * (n - 1) + 1
    h_floor = int(h)
    h_frac = h - h_floor

    # h_floor is 1-based index into sorted_data
    # If h_floor == n, return last element
    if h_floor >= n:
        return float(sorted_data[-1])
    else:
        lower = sorted_data[h_floor - 1]
        upper = sorted_data[h_floor]
        return float(lower + h_frac * (upper - lower))
```

This follows numpy.percentile's 'linear' method exactly:

- Sort the data
- Compute fractional rank h = (p/100)*(n-1)+1
- Interpolate between sorted_data[h_floor - 1] and sorted_data[h_floor]

For p=0 or p=100 it returns min/max respectively.

