def test_extra_spaces_ignored():
    # Leading/trailing whitespace stripped from tokens, blanks removed
    assert tokenize('  hello   world  ') == ['hello', 'world']

def test_custom_delimiter():
    assert tokenize('a,b,c', ',') == ['a', 'b', 'c']

