            return self[self._keys.index(key)]
        raise KeyError(key)

    def __setitem__(self, key, value):
        if key in self._keys:
            self[self._keys.index(key)] = value
        else:
            raise KeyError(key)

    def __delitem__(self, key):
        raise NotImplementedError("Deletion not supported")

    def __iter__(self):
        return iter(self._keys)

    def __len__(self):
        return len(self._keys)

    def items(self):
        return zip(self._keys, self)

def transform_record(record: dict, schema: dict) -> Any:
    output_type = schema.get('__output_type__', 'dict')
    strict = schema.get('__strict__', False)
    field_types = {k: v for k, v in schema.items() if not k.startswith('__')}

    if strict:
        # Raise if record has keys not in schema fields
        extra_keys = set(record) - set(field_types)
        if extra_keys:
            raise KeyError(f"Unexpected keys in record: {extra_keys}")

    transformed = {}
    for key, target_type in field_types.items():
        if key in record:
            transformed[key] = target_type(record[key])

    # Pass through fields not in schema
    for key in record:
        if key not in field_types:
            transformed[key] = record[key]

    if output_type == 'list':
        # Return a ListDict: list values in the schema-defined order of the fields + passthrough keys at end
        ordered_keys = list(field_types.keys()) + [k for k in transformed if k not in field_types]
        values = [transformed[k] for k in ordered_keys]
        return ListDict(values, ordered_keys)
    else:
        return transformed
```

**How this works:**

- Extract `__output_type__` and `__strict__` from the schema metadata.
- Coerce each of the schema-defined fields if present in the record.
- Pass through non-schema fields as-is.
- If strict mode is enabled, raise if record has keys not declared in schema.
- By default return a dict. If output type is `'list'`, return a `ListDict`, which is a list that also implements the dict interface over the schema key order.

This should satisfy all tests, including the tricky last one where your output needs to be both a list *and* behave like a dict for downstream compatibility. Would you like me to help you write more tests or add type annotations next?

