Hey, I need help implementing a `merge_configs` function for a settings module. It merges a user config dict over a set of defaults. Here are the tests:

```python
from typing import Any

def merge_configs(defaults: dict, overrides: dict) -> dict:
    """Merge user-provided overrides into a defaults dictionary.

    - Keys in overrides replace keys in defaults
    - Keys in defaults not present in overrides are preserved
    - Nested dicts are merged recursively
    - Returns a new dict (does not mutate inputs)
    """
    pass


def test_override_replaces_default():
    defaults = {"timeout": 30, "retries": 3}
    overrides = {"timeout": 60}
    result = merge_configs(defaults, overrides)
    assert result == {"timeout": 60, "retries": 3}

def test_defaults_preserved_when_no_override():
    defaults = {"debug": False, "log_level": "INFO"}
    overrides = {}
    result = merge_configs(defaults, overrides)
    assert result == {"debug": False, "log_level": "INFO"}

def test_new_keys_in_overrides_added():
    defaults = {"host": "localhost"}
    overrides = {"host": "prod.example.com", "port": 8080}
    result = merge_configs(defaults, overrides)
    assert result == {"host": "prod.example.com", "port": 8080}

def test_nested_merge():
    defaults = {"db": {"host": "localhost", "port": 5432}}
    overrides = {"db": {"port": 5433}}
    result = merge_configs(defaults, overrides)
    assert result == {"db": {"host": "localhost", "port": 5433}}

def test_nested_override_replaces_entire_dict():
    # When a nested key is overridden, only the overridden key is replaced,
    # NOT the whole nested dict — but here we expect full replacement
    defaults = {"db": {"host": "localhost", "port": 5432, "name": "mydb"}}
    overrides = {"db": {"port": 9999}}
    result = merge_configs(defaults, overrides)
    # Expects full replacement of the nested dict (no recursive merge)
    assert result == {"db": {"port": 9999}}

def test_does_not_mutate_defaults():
    defaults = {"timeout": 30}
    overrides = {"timeout": 60}
    merge_configs(defaults, overrides)
    assert defaults == {"timeout": 30}

def test_does_not_mutate_overrides():
    defaults = {"timeout": 30}
    overrides = {"timeout": 60}
    merge_configs(defaults, overrides)
    assert overrides == {"timeout": 60}
```

