I'm implementing a small URL routing helper for a web framework. Please implement the `match_route` function — here are all the tests:

```python
import re
from typing import Optional, Dict

def match_route(pattern: str, path: str) -> Optional[Dict[str, str]]:
    """
    Match a URL path against a route pattern and extract path parameters.

    Patterns use curly braces for named parameters: e.g., '/users/{id}'
    Parameters match one or more non-slash characters by default.
    A trailing '/*' in the pattern matches any suffix (wildcard).

    Returns a dict of captured parameters if the pattern matches,
    or None if it does not match.
    """
    pass


def test_static_match():
    assert match_route('/home', '/home') == {}

def test_static_no_match():
    assert match_route('/home', '/about') is None

def test_single_param():
    assert match_route('/users/{id}', '/users/42') == {'id': '42'}

def test_multi_param():
    assert match_route('/orgs/{org}/repos/{repo}', '/orgs/acme/repos/widget') == {
        'org': 'acme', 'repo': 'widget'
    }

def test_param_does_not_cross_slash():
    # Parameters should NOT match across slashes
    assert match_route('/users/{id}', '/users/42/profile') is None

def test_wildcard_suffix():
    assert match_route('/static/*', '/static/css/main.css') == {}

def test_wildcard_with_param():
    assert match_route('/cdn/{version}/*', '/cdn/v2/assets/logo.png') == {'version': 'v2'}

def test_trailing_slash_sensitive():
    # Pattern without trailing slash does not match path with trailing slash
    assert match_route('/users/{id}', '/users/42/') is None

def test_empty_param_no_match():
    # Parameters require at least one character
    assert match_route('/users/{id}', '/users/') is None

def test_wildcard_matches_single_segment():
    assert match_route('/files/*', '/files/readme.txt') == {}

def test_numeric_and_alpha_params():
    assert match_route('/items/{sku}', '/items/ABC-123') == {'sku': 'ABC-123'}

def test_wildcard_matches_root_suffix():
    # A wildcard after a param can match even a bare slash continuation
    assert match_route('/cdn/{version}/*', '/cdn/v2/') == {'version': 'v2'}
```

