    """Split text into tokens by delimiter, stripping whitespace from each token.
    Empty tokens (after stripping) should be excluded from the result.
    """
    return [t for t in text.split(delimiter) if t.strip()]

def test_basic_split():
    assert tokenize('hello world foo') == ['hello', 'world', 'foo']

def test_extra_spaces_ignored():
    # Leading/trailing whitespace stripped from tokens, blanks removed
    assert tokenize('  hello   world  ') == ['hello', 'world']

def test_custom_delimiter():
    assert tokenize('a,b,c', ',') == ['a', 'b', 'c']

def test_empty_string():
    assert tokenize('') == []

def test_only_delimiters():
    assert tokenize('   ') == []

def test_preserve_empty_tokens():
    # Empty tokens between delimiters should be preserved as empty strings
    assert tokenize('a,,b', ',') == ['a', '', 'b']

def test_single_token():
    assert tokenize('hello') == ['hello']

def test_custom_delimiter_strips_whitespace():
    assert tokenize('  a , b , c  ', ',') == ['a', 'b', 'c']
```

